def load_questions():
    questions = []
    legacy = ROOT / 'questions.json'
    if legacy.exists():
        for q in json.loads(legacy.read_text(encoding='utf-8')):
            if q['id'] in (27, 28, 29, 30):
                continue
            q = dict(q)
            q['topic'] = {'Automation':'Selenium','Git':'Git и CI','ISTQB':'ISTQB CTFL'}.get(q['topic'], q['topic'])
            if q['id'] == 32:
                q['topic'] = 'Git и CI'
            q.update(kind='choice', stage=1, version=1)
            questions.append(q)
    for i, line in enumerate(DATA.strip().splitlines(), 1001):
        parts = line.split('~')
        if len(parts) != 8:
            raise ValueError(f'Invalid bank record {i}: {len(parts)} fields')
        topic, stage, prompt, correct, w1, w2, w3, explanation = parts
        choices = [correct, w1, w2, w3]
        random.Random(i).shuffle(choices)
        questions.append(dict(id=i, topic=topic, stage=int(stage), kind='choice', question=prompt, choices=choices, answer=choices.index(correct), explain=explanation, version=1))
    for i, (prompt, sql, stage, ordered, explanation) in enumerate(SQL_TASKS, 5001):
        questions.append(dict(id=i,topic='SQL',stage=stage,kind='sql',question=prompt,answer=sql,explain=explanation,ordered=ordered,version=1))
    for i, (topic, prompt, model, rubric) in enumerate(INTERVIEWS, 6001):
        questions.append(dict(id=i,topic=topic,stage=3,kind='interview',question=prompt,answer=model,explain='Сравни свой ответ с эталоном и отметь только те пункты, которые действительно были в твоём ответе. Это самооценка, не AI-проверка.',rubric=rubric,version=1))
    for q in questions:
        q['source'] = SOURCES[q['topic']]
    if len({q['id'] for q in questions}) != len(questions):
        raise ValueError('Duplicate IDs')
    return questions

QUESTIONS = load_questions()
BY_ID = {q['id']: q for q in QUESTIONS}
